// Original A2 foundation route. No official exam questions are reproduced.
const s=(title,text,english,examples)=>({title,text,english,examples});
const q=(prompt,correct,others,why,whyEn)=>({prompt,options:[correct,...others],answer:0,why,whyEn});
const unit=(id,title,tag,goal,sections,quiz,chunks,speak,write,model,visual)=>({id,level:'A2',title,tag,goal,sections,quiz,chunks,speak,write,model,visual,minutes:25,help:sections[0].english});
export const a2Lessons=[
unit('a2-identidad','Presentarte y describir','Identidad y concordancia','Presentarte, describir personas y construir frases que concuerdan.',[
 s('Una frase con sentido','Usa ser para identificar y describir: soy americana, soy profesora, mi hermana es amable. Estar expresa una situación o un estado: estoy en casa, estoy cansada. No memorices permanente frente a temporal como regla absoluta: la ubicación de una ciudad también usa estar. Primero decide qué quieres comunicar.','Use ser for identity and description, and estar for location or a state. Permanent versus temporary is not a reliable general rule. Decide what relationship the sentence expresses before choosing the verb.',['Soy de Florida y estoy en Madrid.','Mi hermana es simpática; hoy está cansada.']),
 s('Las palabras trabajan juntas','El artículo y el adjetivo concuerdan con el nombre: una casa pequeña, unos pisos pequeños. Aprende los nombres con su artículo; el problema y la mano son excepciones frecuentes. Muchos adjetivos terminados en -e no cambian de género: una persona amable, un vecino amable. Sí cambian de número: amables.','The article and adjective agree with the noun. Learn each noun with its article, including el problema and la mano. Many adjectives ending in -e have one gender form but still take a plural ending.',['La habitación es pequeña. / Las habitaciones son pequeñas.','Un vecino amable. / Unas vecinas amables.']),
 s('Posesivos y preguntas personales','Mi, tu y su van antes del nombre y cambian en número: mi amigo, mis amigos. No cambian según el género de la persona que posee algo. Para preguntar usa quién, de dónde y cómo: ¿De dónde eres? Puedes omitir yo cuando el verbo ya identifica a la persona. Añádelo cuando quieras contrastar.','Mi, tu and su agree in number with what is owned, not with the owner. Spanish often omits subject pronouns. Use quién, de dónde and cómo for personal questions, with opening and closing question marks.',['Mis padres viven en Florida.','¿Cómo es tu barrio? Es tranquilo.'])],[
 q('Para indicar tu origen: Yo ___ de Florida.','soy',['estoy','hay'],'Ser identifica el origen; la forma de primera persona es soy.','Ser expresses origin. Its first-person form is soy, not estoy.'),
 q('Para indicar tu ubicación actual: Ahora ___ en casa.','estoy',['soy','es'],'La ubicación de una persona se expresa con estar: estoy en casa.','Use estar to locate a person: estoy en casa. This is location, not identity.'),
 q('Completa la concordancia: Las casas son ___.','pequeñas',['pequeña','pequeños'],'Casas es femenino plural; el adjetivo debe tener las mismas marcas.','Casas is feminine plural, so the adjective is pequeñas.'),
 q('Elige el artículo del nombre mano.','la mano',['el mano','los mano'],'Mano es femenino aunque termine en -o: la mano, las manos.','Mano is feminine despite ending in -o: la mano, las manos.'),
 q('Tengo dos hermanas. Completa: ___ hermanas viven en Florida.','Mis',['Mi','Mías'],'Mis acompaña a un nombre plural. Mías no se coloca así delante del nombre.','Before a plural noun use mis. Mías cannot be used in this position.'),
 q('Para preguntar el origen, elige la pregunta adecuada.','¿De dónde eres?',['¿Dónde estás ahora?','¿Cuántos años tienes?'],'De dónde pregunta por el origen; las otras preguntas piden ubicación o edad.','De dónde asks about origin; the other questions ask about location or age.')],
 ['soy de','ahora estoy en','mi familia vive en','mi barrio es'],
 'Preséntate durante 45 segundos: origen, lugar actual, familia y una descripción.',
 'Escribe 50–70 palabras para presentarte. Usa ser, estar y dos posesivos.',
 'Soy de Florida y ahora estoy en España. Mi familia vive en Estados Unidos. Mi hermana es muy amable y mis padres son simpáticos. Mi barrio es tranquilo. Hoy estoy contenta porque tengo tiempo para estudiar y después voy a pasear con mi pareja.','identity'),
unit('a2-presente','Hablar de lo que haces','Presente y preguntas','Hablar de trabajo, hábitos y actividades con verbos frecuentes.',[
 s('Tres familias de verbos','Para yo, tú y ella compara hablar: hablo, hablas, habla; comer: como, comes, come; vivir: vivo, vives, vive. Nosotros usamos hablamos, comemos y vivimos. Vosotros es frecuente en España; ustedes usa formas de tercera persona plural: hablan, comen, viven. Aprende una frase completa con cada forma.','Regular present verbs belong to -ar, -er and -ir families. Nosotros uses hablamos, comemos and vivimos. Spain often uses vosotros; ustedes takes third-person plural forms in both polite Spanish and everyday American varieties.',['Trabajo por la mañana y vivo cerca del centro.','Nosotros comemos en casa. / Ustedes comen en casa.']),
 s('Irregulares que se usan mucho','Memoriza tengo, hago, voy, sé y puedo con situaciones reales, no solo en una lista. En poder aparece puedo pero nosotros podemos. Saber se usa para información o habilidades; conocer, para personas y lugares conocidos. Puedes decir sé cocinar, conozco Madrid y no sé la respuesta.','Practise high-frequency irregular forms in short personal sentences: tengo, hago, voy, sé and puedo. Poder changes its stem in puedo but not podemos. Saber refers to information or a skill; conocer refers to familiarity.',['Tengo una pregunta y no sé la respuesta.','¿Puedes venir? Nosotros podemos ir después.']),
 s('Negar y preguntar sin do','Pon no delante del verbo para negar: no trabajo los domingos. No añadas un verbo auxiliar equivalente a do al preguntar. La pregunta puede conservar el orden de una afirmación: ¿Trabajas aquí? Qué, dónde, cuándo y a qué hora piden información diferente. Lee primero qué dato necesitas.','Put no before the verb for a negative statement. Spanish questions do not need an auxiliary equivalent to English do. Choose the question word according to the information you need: place, time, activity or reason.',['¿Dónde trabajas? Trabajo en una escuela.','¿A qué hora comes? Como a las dos.'])],[
 q('Completa en presente: Nosotros ___ español cada día.','hablamos',['hablan','hablas'],'Nosotros exige la terminación -amos en el presente de hablar.','Nosotros takes hablamos, the first-person plural of hablar.'),
 q('Completa en presente: Tú ___ en Florida.','vives',['vivo','vivimos'],'La segunda persona singular del presente de vivir es vives.','The present form of vivir for tú is vives.'),
 q('Completa en presente: Yo ___ una pregunta.','tengo',['tiene','tenemos'],'Tener tiene la primera persona irregular tengo.','Tener has the irregular first-person form tengo.'),
 q('Completa en presente: Nosotros ___ salir a las seis.','podemos',['puedemos','puedo'],'El cambio de raíz de puedo no aparece en nosotros: podemos.','There is no stem change in nosotros: podemos, not puedemos.'),
 q('Pregunta por el lugar de trabajo.','¿Dónde trabajas?',['¿Cuándo trabajas?','¿Qué comes?'],'Dónde solicita un lugar; cuándo solicita un momento.','Dónde asks about a place, while cuándo asks about time.'),
 q('Tengo la información: Yo ___ la dirección de la tienda.','sé',['sabo','conozco de'],'Saber expresa conocer un dato; su primera persona es sé.','Saber expresses knowing information, and the first-person form is sé.')],
 ['trabajo en','vivo cerca de','no sé la respuesta','puedo ir a'],
 'Explica tres actividades habituales y haz dos preguntas sobre la rutina de tu pareja.',
 'Escribe 60 palabras sobre un día normal. Incluye una negación y una pregunta.',
 'Trabajo por la mañana y vivo cerca de una estación. Como en casa y estudio español después. No trabajo los domingos. A veces voy al centro con mi pareja. Tengo una libreta para las palabras nuevas. ¿A qué hora estudias tú? Nosotros podemos practicar juntos por la tarde.','time'),
unit('a2-rutina','Tu día y lo que ocurre ahora','Reflexivos y acción en curso','Organizar una rutina y distinguir hábitos de acciones actuales.',[
 s('Me levanto, te levantas','En levantarse y ducharse cambia el pronombre con la persona: me levanto, te levantas, se levanta, nos levantamos. El pronombre no sustituye la terminación del verbo: necesitas ambos. Para indicar horas usa a las ocho, a la una y por la mañana. Une los pasos con primero, después y al final.','With levantarse and ducharse, both the pronoun and the verb match the person: me levanto, te levantas, nos levantamos. Use a las ocho or a la una for a clock time, and connect steps with primero and después.',['Me levanto a las siete y después me ducho.','Nos acostamos a las once.']),
 s('Rutina o acción en desarrollo','El presente describe una rutina: leo por la noche. Estar + gerundio enfoca una acción en curso: estoy leyendo ahora. Forma -ando con hablar y -iendo con comer o vivir. Algunas formas son irregulares: leer → leyendo, dormir → durmiendo. No uses el progresivo para todo lo que en inglés termina en -ing.','The simple present describes a routine, while estar plus gerund views an action in progress. Use hablando, comiendo and viviendo, with irregular leyendo and durmiendo. English uses its progressive form more widely than Spanish.',['Leo antes de dormir. / Ahora estoy leyendo.','Ella está preparando la cena.']),
 s('Frecuencia y orden','Siempre, normalmente, a veces y nunca ayudan a expresar frecuencia. Si nunca va después del verbo, usa no delante: no llego tarde nunca. Si nunca va delante, no añadas no: nunca llego tarde. Para una rutina clara, indica una hora, una actividad y lo que haces después; no necesitas enumerar todas las horas.','Frequency expressions include siempre, normalmente, a veces and nunca. Nunca before the verb already makes the sentence negative; after the verb it normally needs no. Build a routine from a few meaningful steps rather than a long timetable.',['A veces desayuno en una cafetería.','Nunca trabajo de noche. / No trabajo de noche nunca.'])],[
 q('Completa: Yo ___ levanto a las siete.','me',['se','nos'],'El pronombre reflexivo que corresponde a yo es me.','The reflexive pronoun corresponding to yo is me.'),
 q('Completa: Nosotros ___ duchamos por la mañana.','nos',['me','se'],'Nosotros se combina con nos: nos duchamos.','Nosotros takes nos: nos duchamos, not se duchamos.'),
 q('Expresa una acción en curso: Ahora mismo ___ la cena.','estoy preparando',['soy preparando','estoy preparar'],'Una acción en curso se construye con estar + gerundio.','An action in progress uses estar plus a gerund: estoy preparando.'),
 q('Completa el gerundio: Estoy ___ un libro.','leyendo',['leiendo','leer'],'Leer forma el gerundio irregular leyendo.','Leer has the irregular gerund leyendo, with y.'),
 q('Elige la expresión de una hora concreta.','a las ocho',['en las ocho','por las ocho exactas'],'La hora concreta se introduce con a: a las ocho.','Use a for a clock time: a las ocho.'),
 q('Elige la negación estándar.','Nunca llego tarde.',['Nunca no llego tarde.','Llego nunca no tarde.'],'Nunca delante del verbo ya expresa negación; no añadas otro no.','Nunca before the verb already makes the sentence negative.')],
 ['me levanto a las','después de desayunar','a veces','ahora estoy'],
 'Cuenta tu rutina con cuatro pasos. Después di qué estás haciendo ahora.',
 'Escribe una rutina de 60 palabras y añade dos frases sobre este momento.',
 'Normalmente me levanto a las siete. Primero me ducho y después desayuno. Trabajo por la mañana y a veces paseo después de comer. Nunca me acuesto muy tarde. Ahora estoy estudiando español y mi pareja está preparando la cena. Después vamos a ver una película juntos.','time'),
unit('a2-gustos','Gustos, necesidades y sensaciones','Gustar y doler','Expresar gustos y necesidades sin copiar el orden del inglés.',[
 s('Lo que gusta decide el verbo','Con gustar, la cosa o actividad que gusta controla el verbo: me gusta el café, me gustan los libros, me gusta viajar. El pronombre dice a quién le gusta: me, te, le, nos, os, les. No elijas gusta o gustan mirando a la persona que siente el gusto. Busca lo que produce esa sensación.','With gustar, the liked thing or activity controls the verb: me gusta el café, me gustan los libros, me gusta viajar. The pronoun identifies the experiencer. Do not choose the verb from the number of people who like something.',['A Ana le gustan las películas.','A mis padres les gusta viajar.']),
 s('Encantar, interesar y doler','Encantar e interesar siguen un patrón semejante: me encanta esta canción, me interesan los idiomas. Doler también concuerda con lo que duele: me duele la cabeza, me duelen los pies. Usamos el artículo con estas partes del cuerpo en este patrón, no un posesivo calcado del inglés.','Encantar, interesar and doler follow a similar agreement pattern. Say me duele la cabeza and me duelen los pies. In this construction Spanish normally uses an article with body parts, where English often uses a possessive.',['Nos interesa el curso. / Nos interesan los cursos.','Me duele la cabeza; no me duelen los pies.']),
 s('Añadir o negar un gusto','Para compartir una afirmación usa a mí también; para compartir una negación, a mí tampoco. Para contrastar puedes decir a mí no o a mí sí. Tener que + infinitivo expresa una obligación personal: tengo que llamar. Necesitar puede llevar un nombre o un infinitivo: necesito agua, necesito descansar.','Use a mí también to share an affirmative preference and a mí tampoco to share a negative one. Contrast with a mí no or a mí sí. Tener que plus infinitive expresses an obligation; necesitar can be followed by a noun or an infinitive.',['No me gusta madrugar. A mí tampoco.','Tengo que trabajar, pero necesito descansar.'])],[
 q('Completa: Me ___ las ciudades pequeñas.','gustan',['gusta','gustas'],'Las ciudades es plural y controla gustan, aunque me sea singular.','Las ciudades is plural and controls gustan, even though me is singular.'),
 q('Completa: A mis padres les ___ viajar.','gusta',['gustan','gustáis'],'El infinitivo viajar funciona como sujeto singular de gustar.','The infinitive viajar acts as a singular subject, so use gusta.'),
 q('Completa: A Ana ___ interesa este curso.','le',['me','les'],'Ana es la persona que experimenta el interés; le es singular.','Ana is a singular experiencer, represented by le.'),
 q('Completa: Me ___ los pies.','duelen',['duele','duelo'],'Los pies es el sujeto plural que exige duelen.','Los pies is the plural subject, so the verb is duelen.'),
 q('Ana dice «No me gusta madrugar». A ti tampoco te gusta. Responde…','A mí tampoco.',['A mí también.','A mí sí.'],'Tampoco comparte una negación; también comparte una afirmación.','Tampoco agrees with a negative statement, unlike también.'),
 q('Completa una obligación: Tengo ___ llamar al médico.','que',['de','a'],'La construcción de obligación es tener que + infinitivo.','The obligation construction is tener que plus infinitive.')],
 ['me gusta','me interesan','a mí tampoco','tengo que'],
 'Di dos gustos, una cosa que no te gusta y una necesidad de hoy.',
 'Escribe 50 palabras sobre tus gustos. Incluye gusta y gustan.',
 'Me gusta viajar y me gustan las ciudades pequeñas. A mi pareja le interesa la historia y a mí también. No me gusta madrugar. Hoy me duelen un poco los pies porque he caminado mucho. Tengo que descansar y después necesito comprar comida para la cena.','gustar'),
unit('a2-lugares','Orientarte y hablar de tu casa','Hay, estar y preposiciones','Describir qué hay, localizar lugares y comprender indicaciones sencillas.',[
 s('Presentar o localizar','Hay introduce la existencia: hay una farmacia, hay dos parques. La forma hay no cambia con el número. Estar localiza algo identificado: la farmacia está cerca, los parques están al norte. Una pregunta con dónde está pide ubicación; una pregunta con hay pide saber si existe algo en ese lugar.','Hay introduces something that exists and does not change with number. Estar locates an identified person or thing: la farmacia está cerca. Dónde está asks for its location, while hay asks whether something exists in that place.',['En mi barrio hay una biblioteca.','La biblioteca está al lado de la estación.']),
 s('Un mapa de relaciones','Aprende cerca de, lejos de, delante de, detrás de, entre y al lado de como grupos completos. La preposición se mantiene al añadir un nombre: cerca de mi casa. De + el se contrae en del: al lado del parque. A + el se contrae en al: voy al centro. No contraigas a la ni de la.','Learn location expressions as complete chunks: cerca de, detrás de and al lado de. De plus el contracts to del, and a plus el to al. There is no corresponding contraction for de la or a la.',['La tienda está entre el banco y la farmacia.','Voy al mercado; vengo del mercado.']),
 s('Indicaciones que puedes seguir','Para dar instrucciones sencillas a tú usa sigue recto, gira a la derecha, cruza la calle y toma la segunda calle. Antes de actuar, pide repetir si lo necesitas: ¿Puedes decirlo otra vez? Distingue a la derecha de la plaza, que ubica, y gira a la derecha, que indica un cambio de dirección.','Short directions use forms such as sigue recto, gira a la derecha and cruza la calle. Ask for repetition when needed. A la derecha de locates something relative to a landmark; gira a la derecha instructs a turn.',['Sigue recto y gira a la izquierda.','¿Está lejos? No, está a cinco minutos andando.'])],[
 q('Presenta la existencia: En esta calle ___ dos cafeterías.','hay',['están','son'],'Hay presenta algo que existe y permanece igual en singular o plural.','Hay introduces existence and is unchanged for singular or plural nouns.'),
 q('Localiza un lugar conocido: La estación ___ junto al parque.','está',['hay','es'],'La estación ya está identificada; estar indica su ubicación.','La estación is already identified. Estar tells us its location.'),
 q('Completa: La farmacia está cerca ___ mi casa.','de',['a','por'],'Cerca de se aprende como un grupo que conserva la preposición de.','Learn cerca de as a complete location expression, retaining de.'),
 q('Contrae a + el: Voy ___ mercado.','al',['a el','del'],'A + el forma al en este grupo nominal; del corresponde a de + el.','A plus el contracts to al. Del is de plus el.'),
 q('Completa una indicación: Gira a la ___.','derecha',['recto','cerca'],'Girar a la derecha expresa un cambio de dirección. Sigue recto es otra instrucción.','Gira a la derecha asks for a right turn. Sigue recto is a different instruction.'),
 q('Indica una posición entre dos lugares.','La tienda está entre el banco y la farmacia.',['La tienda está lejos.','La tienda es pequeña.'],'Entre sitúa la tienda con dos puntos de referencia explícitos.','Entre locates the shop using two named reference points.')],
 ['en mi barrio hay','está al lado de','sigue recto','¿puedes repetir?'],
 'Describe tres lugares de tu barrio y explica cómo llegar a uno.',
 'Escribe 60 palabras para explicar dónde está tu casa y qué hay cerca.',
 'En mi barrio hay un mercado, una farmacia y dos parques. Mi casa está cerca de la estación y al lado de una cafetería. Para llegar desde la estación, sigue recto y gira a la derecha. La cafetería está delante de un parque pequeño. Podemos tomar un café allí.','identity'),
unit('a2-compras','Comprar y comparar','Cantidad, precio y comparación','Pedir productos, expresar cantidades y comparar opciones.',[
 s('Muy o mucho','Muy acompaña un adjetivo o adverbio: muy caro, muy bien. Mucho acompaña un verbo sin cambiar: estudio mucho. Ante un nombre cambia en género y número: mucho pan, mucha agua, muchos libros, muchas bolsas. La elección depende de la palabra que modifica, no de la traducción inglesa very o a lot.','Muy modifies an adjective or adverb: muy caro, muy bien. Mucho after a verb is unchanged. Before a noun it agrees in gender and number: mucha agua, muchos libros. Identify what is being modified before choosing the form.',['La fruta está muy cara; no quiero muchas bolsas.','Tengo mucha hambre, pero como poco.']),
 s('Comparaciones sencillas','Compara cualidades con más + adjetivo + que, menos + adjetivo + que y tan + adjetivo + como. Mejor y peor son comparativos frecuentes: este café es mejor, no más mejor. Mayor y menor pueden expresar edad. El contexto y la cualidad comparada importan más que memorizar una traducción aislada.','Compare qualities with más or menos plus adjective plus que, and tan plus adjective plus como. Mejor and peor already express comparison, so do not add más. Mayor and menor can compare ages. Name the actual quality you are comparing.',['Esta bolsa es más grande que la otra.','Este café es tan bueno como aquel.']),
 s('Preguntar y pedir en una tienda','Cuánto cambia con un nombre: cuánto pan, cuánta leche, cuántas manzanas. Para el precio pregunta ¿Cuánto cuesta? o ¿Cuánto cuestan? según el producto. Puedes pedir con quiero, quería o ¿Me pones…? según el contexto. Practica unidades: un kilo de, una botella de y doscientos gramos de.','Cuánto agrees with a following noun: cuánta leche, cuántas manzanas. Cuesta or cuestan agrees with the priced item. Practise quantities as chunks: un kilo de, una botella de and doscientos gramos de, with a polite request.',['¿Cuánto cuestan estas manzanas?','Quería una botella de agua, por favor.'])],[
 q('Completa: Este bolso es ___ caro.','muy',['mucho','muchas'],'Caro es un adjetivo; el intensificador delante de un adjetivo es muy.','Caro is an adjective, so its intensifier is muy.'),
 q('Completa: Necesito ___ agua.','mucha',['mucho','muy'],'Agua es femenino; mucha concuerda con ese nombre.','Agua is feminine, so the quantity form is mucha.'),
 q('Completa una comparación de superioridad: Este piso es más grande ___ aquel.','que',['como','de'],'La comparación usa más + adjetivo + que.','A comparison with más plus adjective uses que.'),
 q('Completa una comparación de igualdad: Es ___ fácil como el otro.','tan',['tanto','más'],'Tan + adjetivo + como expresa igualdad de cualidad.','Tan plus adjective plus como expresses equality of a quality.'),
 q('Completa: ¿Cuánto ___ estas camisetas?','cuestan',['cuesta','costas'],'Estas camisetas es plural; el verbo también debe ser plural.','Estas camisetas is plural, so the verb must be cuestan.'),
 q('Elige el comparativo estándar de bueno.','mejor',['más mejor','más bueno mejor'],'Mejor ya expresa comparación; más mejor duplica la marca.','Mejor already expresses comparison; más mejor doubles the marker.')],
 ['quería un kilo de','¿cuánto cuesta?','es más barato que','tengo mucha hambre'],
 'Simula una compra: pide un producto y compara dos opciones.',
 'Escribe una lista con cantidades y un mensaje de 50 palabras sobre la compra.',
 'Necesito una botella de agua, un kilo de tomates y dos bolsas pequeñas. Estos tomates son más baratos que los otros, pero parecen buenos. La tienda está muy cerca de casa. ¿Cuánto cuestan las manzanas? Quería también un poco de pan. Hoy tengo mucha hambre.','agreement'),
unit('a2-pronombres','Evitar repetir nombres','Objeto directo y destinatario','Reconocer qué representa un pronombre y colocar lo, la, los y las.',[
 s('Qué cosa recibe la acción','Lo, la, los y las pueden sustituir una cosa ya mencionada: compro el libro → lo compro; veo las fotos → las veo. Identifica primero el nombre y comprueba su género y número. El pronombre no cambia según el género de quien habla. Hablar de las fotos exige las aunque yo sea un hombre.','Lo, la, los and las can replace an already mentioned direct object. Match the gender and number of that object, not the speaker. Las fotos becomes las even when the person speaking is male. First identify the noun being replaced.',['Tengo la llave. → La tengo.','Busco los billetes. → Los busco.']),
 s('Dónde va el pronombre','Con un verbo conjugado sencillo, el pronombre va delante: la compro, no la compro. Con un infinitivo se puede unir al final: comprarla. En voy a comprarla también puedes colocarlo antes del conjunto: la voy a comprar. No lo insertes entre a y comprar. Lee la frase completa al comprobar su posición.','Before a simple conjugated verb, the pronoun goes first: la compro. Attach it to an infinitive in comprarla. With voy a comprarla you can also say la voy a comprar; do not insert it between a and the infinitive.',['Voy a comprarlo. / Lo voy a comprar.','No las veo; necesito buscarlas.']),
 s('Un primer puente al destinatario','En envío las fotos a Ana hay una cosa enviada y una destinataria. Las sustituye las fotos. Le puede representar a Ana; delante de las cambia a se: se las envío. Puedes conservar a Ana para aclarar a quién: se las envío a Ana. Esta combinación es un puente hacia B1; empieza distinguiendo cosa y destinatario.','In envío las fotos a Ana, the photos are the direct object and Ana is the recipient. Las replaces the photos. Le becomes se before las. Se las envío a Ana is valid: a Ana identifies the recipient already represented by se.',['Envío las fotos a Ana. → Las envío a Ana.','Envío las fotos a Ana. → Se las envío a Ana.'])],[
 q('Sustituye el libro: Compro el libro. → ___ compro.','Lo',['La','Los'],'Libro es masculino singular y se representa con lo.','Libro is masculine singular and is represented by lo.'),
 q('Sustituye las llaves: Tengo las llaves. → ___ tengo.','Las',['La','Los'],'Las llaves es femenino plural; el pronombre es las.','Las llaves is feminine plural, so the pronoun is las.'),
 q('Elige una colocación correcta al sustituir la mochila.','La voy a comprar.',['Voy la a comprar.','Voy a la comprar.'],'El pronombre puede preceder a la perífrasis: la voy a comprar.','The pronoun can precede the whole construction: la voy a comprar.'),
 q('Une lo al infinitivo comprar.','comprarlo',['comprar lo','lo comprarlo'],'El pronombre unido a un infinitivo forma una sola palabra: comprarlo.','A pronoun attached to an infinitive forms one word: comprarlo.'),
 q('En «Se las envío a Ana», ¿qué representa las?','las fotos mencionadas',['Ana','la persona que envía'],'Las representa el objeto femenino plural, no a la destinataria.','Las represents the mentioned feminine plural object, not the recipient.'),
 q('En «Se las envío a Ana», ¿qué representa se?','a Ana, la destinataria',['las fotos','la persona que envía'],'Se es la forma que toma le delante de las y representa al destinatario.','Se is the form taken by le before las; it represents the recipient.')],
 ['lo tengo','no la encuentro','voy a comprarlo','se las envío a'],
 'Elige tres objetos y explica si los tienes, los buscas o vas a comprarlos.',
 'Escribe cuatro pares: frase con nombre y frase con pronombre. Explica a quién envías algo.',
 'Tengo el libro y lo leo por la tarde. No encuentro las llaves: las busco en la mochila. Necesito una botella de agua y voy a comprarla. He hecho unas fotos del barrio. Las envío a Ana. También puedo decir: se las envío a Ana.','pronouns'),
unit('a2-ayer','Contar lo que hiciste','Indefinido y experiencias','Contar una secuencia sencilla de acontecimientos pasados.',[
 s('Una acción vista como completa','El pretérito indefinido presenta un acontecimiento como un conjunto delimitado: ayer compré pan, el sábado visitamos un museo. No significa que todo fuera breve. Compara hablé, hablaste, habló con comí, comiste, comió. Nosotros usamos hablamos o comimos; en -ar hablamos coincide con el presente y el contexto ayuda.','The preterite views an event as a bounded whole, not necessarily a short event. Compare hablé, hablaste, habló and comí, comiste, comió. Hablamos has the same form in present and preterite; context identifies the time.',['Ayer trabajé ocho horas.','El sábado visitamos el museo y después comimos.']),
 s('Formas irregulares esenciales','Aprende fui, tuve, estuve e hice en frases. Fui puede pertenecer a ir o a ser: fui al mercado, fui estudiante. Con él o ella aparece fue y con nosotros fuimos. Hizo no lleva tilde. Para contar una salida, ordena dos o tres acciones con primero, después y al final, sin añadir tiempos nuevos todavía.','Practise fui, tuve, estuve and hice in whole sentences. Fui can belong to ir or ser; the rest of the sentence tells you which. Hizo has no written accent. Start with a short sequence linked by primero, después and al final.',['Fui al centro y tuve que esperar.','Ella hizo la cena y nosotros estuvimos en casa.']),
 s('Experiencias hasta ahora','Haber en presente + participio forma he viajado, has comido y hemos vivido. El participio con haber no concuerda con el objeto: he comprado dos camisetas. Aprende hecho y visto. El uso de he ido frente a fui cambia entre regiones; no trates una variante americana como error solo por una preferencia de España.','Present haber plus participle forms he viajado, has comido and hemos vivido. The participle does not agree with the object. Learn hecho and visto. The distribution of he ido and fui varies by region; a different regional preference is not automatically an error.',['Nunca he visitado ese museo.','Hoy he ido al centro. / Hoy fui al centro, en otras variedades.'])],[
 q('Usa pretérito indefinido, yo: Ayer ___ pan.','compré',['compro','compraré'],'La instrucción pide indefinido de comprar para yo: compré, con tilde.','The instruction asks for the yo preterite of comprar: compré, with an accent.'),
 q('Usa pretérito indefinido, ella: Ana ___ al centro.','fue',['fui','fuimos'],'La tercera persona del indefinido de ir es fue.','The third-person singular preterite of ir is fue.'),
 q('Usa pretérito indefinido, nosotros: ___ en casa.','estuvimos',['estuvieron','estuve'],'Nosotros exige estuvimos en el indefinido de estar.','The nosotros preterite of estar is estuvimos.'),
 q('Usa pretérito indefinido, ella: ___ la cena.','hizo',['hizó','hice'],'Hizo corresponde a ella y no lleva tilde.','Hizo is the ella form and takes no written accent.'),
 q('Completa el participio: He ___ dos camisetas.','comprado',['compradas','comprada'],'Con haber el participio no concuerda con camisetas.','After haber, the participle does not agree with camisetas.'),
 q('Completa el perfecto de ver: Nunca he ___ ese museo.','visto',['vido','viendo'],'El participio irregular de ver es visto.','Ver has the irregular past participle visto.')],
 ['ayer fui a','después compré','al final volvimos','nunca he visto'],
 'Cuenta una salida de ayer con tres acciones y una expresión de orden.',
 'Escribe 60–80 palabras sobre una salida terminada. Añade una experiencia con he + participio.',
 'Ayer fui al centro con mi pareja. Primero compramos fruta en el mercado. Después visitamos una tienda y comimos en una cafetería. Al final volvimos a casa en autobús. Fue una tarde tranquila. He visitado ese mercado varias veces, pero nunca he comido en el restaurante de al lado.','time'),
unit('a2-antes','Cómo era antes','Imperfecto y contraste básico','Describir hábitos pasados y distinguir un hábito de un acontecimiento.',[
 s('Mirar dentro de una situación','El imperfecto describe hábitos y contexto: de niña vivía en Florida, iba a la playa, tenía una bicicleta. En -ar aparece hablaba; en -er e -ir, comía y vivía. Las formas irregulares básicas son era, iba y veía. No memorices pasado largo frente a corto: el punto de vista importa más que la duración.','The imperfect describes past habits and background: vivía, iba and tenía. Regular patterns are hablaba, comía and vivía, with irregular era, iba and veía. Long versus short is not the rule; viewpoint matters more than duration.',['De niña vivía cerca de la playa.','Antes iba al trabajo en coche todos los días.']),
 s('Hábito y acontecimiento','Compara iba a la playa cada domingo y fui a la playa el domingo pasado. La primera frase presenta repetición como hábito; la segunda, una visita completa. Un periodo largo también puede delimitarse: viví allí diez años y después me mudé. En esta unidad empieza con pares claros; los relatos más complejos se trabajan en B1.','Compare a past habit, iba a la playa cada domingo, with a completed visit, fui el domingo pasado. A long period can also be bounded: viví allí diez años. Start with clear contrasts before combining several layers of a B1 narrative.',['Antes estudiaba de noche; ayer estudié por la mañana.','Viví allí diez años y después me mudé.']),
 s('Comparar entonces y ahora','Antes y ahora organizan un cambio: antes trabajaba en una tienda, ahora trabajo en casa. Puedes comparar cualidades con más… que o tan… como. Usa porque para una causa y pero para un contraste sencillo. No hace falta usar subjuntivo para describir estos cambios cotidianos con claridad.','Antes and ahora organise a change between past and present. Add a simple comparison with más… que or tan… como. Porque gives a reason and pero introduces contrast. You can describe these everyday changes without using the subjunctive.',['Antes mi barrio era más tranquilo que ahora.','Ahora camino más porque vivo cerca del centro.'])],[
 q('Usa imperfecto, yo: De niña ___ en Florida.','vivía',['viví','vivo'],'La instrucción pide imperfecto de vivir: vivía, con tilde.','The instruction asks for the imperfect of vivir: vivía.'),
 q('Usa imperfecto, yo: Antes ___ a la playa cada domingo.','iba',['fui','voy'],'Iba es la forma irregular del imperfecto de ir.','Iba is the irregular imperfect form of ir.'),
 q('Usa imperfecto de ser, ella: Mi escuela ___ pequeña.','era',['fue','es'],'La tercera persona del imperfecto de ser es era.','The third-person singular imperfect of ser is era.'),
 q('Elige la frase que presenta explícitamente una visita terminada.','Fui a la playa y después volví a casa.',['Iba a la playa cada domingo.','Voy a la playa a menudo.'],'Fui y volví delimitan una visita; iba describe una repetición habitual.','Fui and volví bound one visit; iba describes a past habit.'),
 q('Usa imperfecto, nosotros: Antes ___ en una tienda.','trabajábamos',['trabajamos','trabajaron'],'El imperfecto de trabajar para nosotros es trabajábamos, con tilde.','The nosotros imperfect of trabajar is trabajábamos, with an accent.'),
 q('Completa una causa: Camino más ___ vivo cerca del centro.','porque',['pero','y'],'Porque introduce la razón del cambio; pero introduciría contraste.','Porque introduces the reason; pero would introduce a contrast.')],
 ['antes vivía en','de niña iba a','ahora trabajo en','es más tranquilo que'],
 'Compara tu vida de antes y de ahora con tres pares de frases.',
 'Escribe 60 palabras sobre cómo era tu rutina en Florida y cómo es ahora.',
 'Antes vivía en Florida y trabajaba lejos de casa. Iba al trabajo en coche y escuchaba música durante el viaje. Ahora vivo cerca del centro y camino más. Mi rutina es diferente, pero me gusta. El domingo pasado fui a un parque y después volví a casa para descansar.','time'),
unit('a2-planes','Planes y acuerdos sencillos','Ir a, poder y tener que','Proponer un plan, pedir ayuda y expresar una obligación.',[
 s('Una intención con ir a','Ir a + infinitivo expresa una intención o previsión: voy a estudiar, vamos a viajar. Cambia ir según la persona y conserva a y el infinitivo. No escribas voy estudiar ni voy a estudio. Una expresión como mañana no obliga a usar futuro simple: mañana voy a llamar y mañana llamo pueden ser naturales en su contexto.','Ir a plus infinitive expresses an intention: voy a estudiar, vamos a viajar. Conjugate ir but keep a and the infinitive. Mañana does not force a simple future form; Spanish can express a plan in several natural ways.',['Mañana voy a llamar a mi hermana.','El sábado vamos a visitar un museo.']),
 s('Poder, querer y tener que','Poder y querer llevan infinitivo: puedo ir, quiero descansar. Tener que añade una obligación: tengo que trabajar. Hay que es impersonal y expresa necesidad general: hay que reservar. Para pedir ayuda puedes usar ¿Puedes…?, y para proponer, ¿Quieres…? Explica una limitación sin inventar una excusa: no puedo porque trabajo.','Poder and querer take an infinitive: puedo ir, quiero descansar. Tener que expresses a personal obligation; hay que gives an impersonal necessity. Ask with ¿Puedes…? or propose with ¿Quieres…?, and give a simple reason when declining.',['¿Puedes ayudarme con esto?','No puedo ir: tengo que trabajar.']),
 s('Acuerdos y condiciones reales','Para quedar, concreta día, hora y lugar: el sábado, a las seis, en la plaza. Si + presente permite una condición abierta: si hace buen tiempo, vamos a la playa. Porque explica una causa, por eso introduce una consecuencia y pero marca contraste. Compara la función antes de elegir el conector.','When making an arrangement, specify a day, time and place. Si plus present can express an open condition: si hace buen tiempo, vamos a la playa. Porque gives a reason, por eso a consequence, and pero a contrast.',['Si hace buen tiempo, vamos al parque.','Tengo que trabajar, por eso no puedo ir por la mañana.'])],[
 q('Completa: Mañana voy ___ estudiar español.','a',['de','que'],'Ir a + infinitivo conserva la preposición a.','The construction ir a plus infinitive retains a.'),
 q('Completa: Nosotros ___ a visitar el museo.','vamos',['voy','van'],'La primera persona plural de ir es vamos.','The first-person plural of ir is vamos.'),
 q('Completa: No puedo ___ hoy.','ir',['voy','iba'],'Poder se combina aquí con un infinitivo: puedo ir.','Poder takes an infinitive here: puedo ir.'),
 q('Completa una obligación: Tenemos ___ reservar.','que',['a','de'],'La obligación personal usa tener que + infinitivo.','A personal obligation uses tener que plus infinitive.'),
 q('Usa presente de hacer: Si ___ buen tiempo, vamos a la playa.','hace',['haga','haría'],'La instrucción pide presente de indicativo: hace. La condición se presenta como abierta.','The instruction asks for present indicative hace in an open condition.'),
 q('Expresa una consecuencia: Trabajo mañana; ___ no puedo ir por la mañana.','por eso',['porque','pero'],'Por eso introduce la consecuencia del horario de trabajo.','Por eso introduces the consequence of the work schedule.')],
 ['voy a','¿quieres venir?','tengo que','si hace buen tiempo'],
 'Propón un plan concreto y responde a una limitación de tu pareja.',
 'Escribe un mensaje de 60 palabras para quedar. Indica día, hora, lugar y una alternativa.',
 'Hola, Ana. El sábado voy a visitar el museo. ¿Quieres venir? Podemos quedar a las seis en la plaza. Tengo que trabajar por la mañana, por eso no puedo ir antes. Si hace buen tiempo, después vamos al parque. Si prefieres otro día, podemos hablar esta tarde y cambiar el plan.','time')
];
