const topic=(id,title,unitId,rule,ruleEn,examples,trap,trapEn,strategy,strategyEn)=>({id,level:'A2',title,unit:unitId,rule,examples,trap,strategy,english:{rule:ruleEn,trap:trapEn,strategy:strategyEn}});
export const a2Topics=[
 topic('a2identity','Identidad, estado y concordancia','a2-identidad','Ser identifica; estar localiza o atribuye un estado. El artículo y el adjetivo concuerdan con el nombre, no con quien habla. Aprende los nombres con su artículo.','Ser identifies; estar locates or describes a state. Articles and adjectives match the noun, not the speaker. Learn nouns with their articles.',['Soy de Florida. / Estoy en España.','La habitación es pequeña. / Las habitaciones son pequeñas.','El problema es difícil.'], 'Permanente o temporal no resuelve todos los usos de ser y estar. La mano es femenino aunque termine en -o.','Permanent versus temporary does not cover all uses. La mano is feminine despite its ending.','Describe dos personas y dos lugares. Subraya artículos y terminaciones que concuerdan.','Describe two people and two places. Mark the matching article and adjective endings.'),
 topic('a2verbs','Presente, reflexivos y acción en curso','a2-rutina','Habla de una rutina con presente y enfoca una acción en curso con estar + gerundio. En reflexivos cambia el pronombre y el verbo: me levanto, nos levantamos.','Use the simple present for a routine and estar plus gerund for an action in progress. Reflexive pronouns and verb endings both match the person.',['Leo por la noche. / Ahora estoy leyendo.','Me levanto a las siete. / Nos levantamos a las siete.','Puedo ir. / Podemos ir.'], 'No copies el progresivo inglés en todas las rutinas ni olvides el pronombre reflexivo.','Do not copy the English progressive into every routine or omit a reflexive pronoun.','Escribe un hábito y lo que ocurre ahora. Después cambia yo por nosotros.','Write one habit and one current action, then change yo to nosotros.'),
 topic('a2likes','Gustar: la cosa controla el verbo','a2-gustos','Con gustar y doler, busca qué gusta o qué duele: me gusta el café, me gustan los libros, me duelen los pies. Me o le señala a quien siente la experiencia.','With gustar and doler, identify the liked or hurting thing: it controls the verb. Me or le identifies the experiencer, not the subject that controls agreement.',['Me gusta leer.','A Ana le gustan las películas.','Me duele la cabeza. / Me duelen los pies.'], 'Varias personas pueden usar gusta si lo que gusta es singular: a mis padres les gusta viajar.','Several people still take gusta when the liked thing or activity is singular.','Rodea lo que gusta y decide si es un nombre singular, plural o un infinitivo.','Circle the liked thing and decide whether it is a singular noun, a plural noun or an infinitive.'),
 topic('a2places','Presentar, localizar y sustituir objetos','a2-lugares','Hay introduce existencia y estar ubica algo identificado. Lo, la, los y las sustituyen un objeto mencionado según su género y número. Conserva las preposiciones de cada expresión.','Hay introduces existence and estar locates an identified referent. Lo, la, los and las replace mentioned objects according to gender and number. Keep each location expression’s preposition.',['Hay una estación. / La estación está cerca.','Está al lado del parque.','Tengo las llaves. → Las tengo.'], 'Hay no cambia en plural: hay dos parques. Cerca de conserva de.','Hay does not change for plural nouns. Cerca de retains de.','Dibuja tres lugares y describe qué hay y dónde están; después sustituye dos objetos por pronombres.','Draw three places and describe their existence and location, then replace two objects with pronouns.'),
 topic('a2past','Un acontecimiento y un hábito pasado','a2-antes','El indefinido presenta un acontecimiento delimitado; el imperfecto, un hábito o contexto. El perfecto se forma con haber + participio invariable. La distribución del perfecto cambia entre regiones.','The preterite bounds an event; the imperfect presents a habit or background. The present perfect uses haber and an unchanging participle. Its distribution varies between Spanish-speaking regions.',['Ayer fui al centro y volví a casa.','Antes iba al centro cada sábado.','He comprado dos libros.'], 'Ayer no decide automáticamente el tiempo y una situación larga puede estar delimitada: viví allí diez años.','Ayer does not automatically decide the tense, and a long situation can be bounded.','Compara antes hacía con ayer hice y explica si presentas hábito o acontecimiento.','Compare antes hacía with ayer hice and say whether you present a habit or an event.'),
 topic('a2plans','Intención, obligación y comparación','a2-planes','Ir a + infinitivo presenta una intención; tener que + infinitivo expresa obligación. Más… que compara superioridad y tan… como igualdad. Porque explica una causa; por eso, una consecuencia.','Ir a plus infinitive expresses intention; tener que expresses obligation. Más… que compares superiority and tan… como equality. Porque gives a reason; por eso gives a consequence.',['Voy a estudiar; tengo que terminar esto.','Es más barato que el otro. / Es tan barato como el otro.','Trabajo, por eso no puedo ir.'], 'Con ir a y tener que, el segundo verbo queda en infinitivo: voy a estudiar, no voy a estudio.','After ir a or tener que, keep the second verb in the infinitive.','Propón un plan con día, hora y lugar; explica una obligación y ofrece una alternativa.','Propose a plan with day, time and place, explain one obligation and offer an alternative.'),
 topic('a2quantity','Muy, mucho y cantidad','a2-compras','Muy modifica adjetivos o adverbios. Mucho modifica verbos sin cambiar y concuerda delante de nombres: muchas preguntas. Tan acompaña adjetivos en la igualdad.','Muy modifies adjectives or adverbs. Mucho stays unchanged with a verb and agrees before a noun: muchas preguntas. Tan accompanies an adjective in an equality comparison.',['Es muy fácil. / Estudio mucho.','Tengo muchas preguntas.','Es tan fácil como aquel.'], 'Mucha agua y mucha hambre son femeninos aunque se diga el agua y el hambre.','Agua and hambre are feminine even when their singular article is el.','Clasifica cada palabra que modificas: nombre, verbo, adjetivo o adverbio.','Classify the word you modify as noun, verb, adjective or adverb.'),
 topic('a2questions','Preguntar por el dato que necesitas','a2-presente','Dónde pide lugar, cuándo tiempo, quién persona, cuánto cantidad y por qué una causa. Cuánto cambia ante un nombre. Las palabras interrogativas llevan tilde.','Dónde asks for place, cuándo for time, quién for a person, cuánto for quantity and por qué for a reason. Cuánto agrees before a noun, and question words take accents.',['¿Dónde trabajas? En una escuela.','¿Cuántas manzanas quieres?','¿Por qué estudias español?'], 'Por qué pregunta; porque introduce la respuesta que expresa la causa.','Por qué asks a question; porque introduces a causal answer.','Escribe una respuesta primero y después la pregunta que pide exactamente ese dato.','Write an answer first, then a question that asks for exactly that information.')
];

const reading=(id,title,type,text,translation,glossary,questions,task,taskEn)=>({id,level:'A2',title,type,text,translation,glossary,questions,task,taskEn});
export const a2Library=[
 reading('lib-a2-1','Un sábado en el barrio','Mensaje',
 'Hola, Ana. El sábado voy al mercado con mi pareja. Normalmente compramos fruta por la mañana, pero esta semana tengo que trabajar hasta las doce. Podemos quedar a la una delante de la farmacia. El mercado está al lado de un parque pequeño y hay una cafetería cerca. Primero quiero comprar tomates y una botella de agua. Después podemos comer en la cafetería. No necesito pan porque todavía hay en casa. Si hace buen tiempo, vamos a pasear por el parque después de comer. Si llueve, podemos ir a mi casa y ver una película. Mi pareja no puede quedarse toda la tarde: tiene una clase a las cinco. ¿Puedes venir? Escríbeme el viernes para confirmar el plan.',
 'Hi Ana. On Saturday I am going to the market with my partner. We usually buy fruit in the morning, but this week I have to work until noon. We can meet at one outside the pharmacy. The market is next to a small park and there is a café nearby. First I want to buy tomatoes and a bottle of water. Then we can eat at the café. I do not need bread because there is still some at home. If the weather is good, we will walk in the park after lunch. If it rains, we can go to my place and watch a movie. My partner cannot stay all afternoon: they have a class at five. Can you come? Write on Friday to confirm the plan.',
 [['quedar','to arrange to meet'],['delante de','in front of'],['todavía','still'],['quedarse','to stay']],[
 q('¿Por qué no van al mercado por la mañana esta semana?','Porque la persona que escribe trabaja hasta las doce.',['Porque el mercado no abre.','Porque Ana está de viaje.'],'El mensaje explica que esta semana tiene que trabajar hasta las doce.','The writer says they have to work until noon this week.'),
 q('¿Dónde proponen quedar?','Delante de la farmacia.',['Dentro del mercado.','En casa de Ana.'],'La propuesta es quedar a la una delante de la farmacia.','The proposed meeting point is outside the pharmacy.'),
 q('¿Qué producto no necesitan comprar?','Pan.',['Tomates.','Agua.'],'No necesitan pan porque todavía hay en casa.','They do not need bread because they still have some at home.'),
 q('¿Cuál es la alternativa si llueve?','Ir a casa y ver una película.',['Pasear por el parque.','Cancelar la clase.'],'El mensaje ofrece la casa y una película como alternativa a la lluvia.','Going home and watching a movie is the rain alternative.'),
 q('¿Qué tiene la pareja a las cinco?','Una clase.',['Una cita en la farmacia.','Una cena.'],'La clase a las cinco limita el tiempo que puede quedarse.','A class at five limits how long the partner can stay.')],
 'Responde con 40 palabras: confirma si puedes ir e indica dónde y cuándo.', 'Reply in about 40 words: confirm whether you can come and name the time and place.'),
 reading('lib-a2-2','Una habitación para compartir','Anuncio',
 'Tenemos una habitación libre en un piso de tres personas. La habitación es pequeña, pero tiene una ventana grande, una cama y una mesa. El piso está en una calle tranquila, a diez minutos andando de la estación. En el barrio hay dos supermercados y una biblioteca. El alquiler de la habitación es de cuatrocientos euros al mes e incluye agua e internet. La electricidad se paga aparte. No hay ascensor: el piso está en la segunda planta. Puedes estudiar o trabajar; no se permite fumar dentro de casa. Puedes visitar la habitación el miércoles o el jueves por la tarde. El sábado no estamos. Para pedir una visita, escribe un mensaje e indica qué día puedes venir.',
 'We have a free room in an apartment shared by three people. The room is small, but has a large window, a bed and a desk. The apartment is on a quiet street, a ten-minute walk from the station. There are two supermarkets and a library in the neighbourhood. Rent is four hundred euros a month and includes water and internet. Electricity is paid separately. There is no elevator: the apartment is on the second floor. We are looking for someone who studies or works and does not smoke inside. You can visit on Wednesday or Thursday afternoon. We are away on Saturday. To arrange a visit, write a message saying which day you can come.',
 [['alquiler','rent'],['aparte','separately'],['ascensor','elevator'],['planta','floor / storey']],[
 q('¿Cómo es la habitación?','Pequeña, con una ventana grande.',['Grande, sin ventana.','Pequeña, sin mesa.'],'El anuncio indica el tamaño y la ventana grande, además de cama y mesa.','The room is small and has a large window, a bed and a desk.'),
 q('¿Cuánto se tarda andando a la estación?','Diez minutos.',['Dos minutos.','Cuarenta minutos.'],'El piso está a diez minutos andando de la estación.','The station is a ten-minute walk away.'),
 q('¿Qué gasto no está incluido en el alquiler?','La electricidad.',['El agua.','Internet.'],'La electricidad se paga aparte; agua e internet sí están incluidos.','Electricity is separate; water and internet are included.'),
 q('¿Qué dificultad puede tener alguien que necesita un ascensor?','El piso está en la segunda planta y no hay ascensor.',['El piso está en la planta baja.','Hay dos ascensores muy pequeños.'],'La combinación de segunda planta y falta de ascensor aparece explícitamente.','The ad explicitly says second floor and no elevator.'),
 q('¿Cuándo se puede visitar?','El miércoles o el jueves por la tarde.',['El sábado por la mañana.','Solo el domingo.'],'El anuncio ofrece miércoles o jueves por la tarde y descarta el sábado.','Visits are offered on Wednesday or Thursday afternoon, not Saturday.')],
 'Escribe un mensaje para pedir una visita y preguntar por un gasto.', 'Write a short message requesting a visit and asking about one expense.'),
 reading('lib-a2-3','La excursión de ayer','Relato',
 'Ayer fui a un pueblo con mi pareja. Salimos de casa a las nueve y tomamos un autobús. El viaje duró una hora. Primero visitamos una plaza y después entramos en un mercado. Compré queso y mi pareja compró unas manzanas. Queríamos comer en un restaurante junto al río, pero estaba cerrado. Por eso comimos en una cafetería de la plaza. La comida fue sencilla y muy buena. Después caminamos hasta un parque. Hacía un poco de frío, así que no nos quedamos mucho tiempo. Volvimos a casa a las seis. Fue un día tranquilo. Nunca he visitado el museo de ese pueblo; la próxima vez quiero ir. Voy a consultar el horario antes de salir.',
 'Yesterday I went to a village with my partner. We left home at nine and took a bus. The trip lasted an hour. First we visited a square and then went into a market. I bought cheese and my partner bought some apples. We wanted to eat at a restaurant by the river, but it was closed. So we ate at a café in the square. The food was simple and very good. Then we walked to a park. It was a little cold, so we did not stay long. We returned home at six. It was a quiet day. I have never visited that village’s museum; next time I want to go. I am going to check the opening hours before leaving.',
 [['tomar un autobús','to take a bus'],['cerrado','closed'],['quedarse','to stay'],['horario','opening hours / schedule']],[
 q('¿Cómo viajaron?','En autobús.',['En tren.','En coche.'],'El relato dice que tomaron un autobús y viajaron durante una hora.','They took a bus for a one-hour trip.'),
 q('¿Qué compró la persona que cuenta la historia?','Queso.',['Manzanas.','Una entrada de museo.'],'La persona dice compré queso; las manzanas las compró su pareja.','The narrator bought cheese; their partner bought apples.'),
 q('¿Por qué comieron en una cafetería?','Porque el restaurante estaba cerrado.',['Porque no había restaurantes.','Porque el museo tenía cafetería.'],'El cierre del restaurante explica el cambio de lugar para comer.','The restaurant being closed explains the change of lunch venue.'),
 q('¿Por qué no se quedaron mucho en el parque?','Porque hacía frío.',['Porque perdieron el autobús.','Porque empezó la clase.'],'El frío se presenta como la razón de no quedarse mucho tiempo.','The cold weather is explicitly the reason for the short stay.'),
 q('¿Qué quieren hacer en otra visita?','Visitar el museo.',['Trabajar en el mercado.','Comprar una casa.'],'La persona quiere visitar el museo que todavía no conoce.','The writer wants to visit the museum they have not visited yet.')],
 'Cuenta una salida terminada en 60 palabras e incluye un cambio de plan.', 'Describe a completed outing in about 60 words, including one change of plan.'),
 reading('lib-a2-4','Un curso por la tarde','Información',
 'El centro del barrio ofrece un curso de fotografía para personas adultas. No necesitas experiencia, pero tienes que llevar un teléfono con cámara o una cámara sencilla. Las clases son los martes y los jueves de seis a siete y media. El curso empieza el diez de noviembre y dura cuatro semanas. La primera semana aprendemos a usar la luz. Después hacemos fotos de objetos y de lugares del barrio. La última clase es en el parque, si hace buen tiempo. Si llueve, trabajamos dentro del centro. El curso cuesta sesenta euros. Para reservar una plaza, hay que escribir al centro antes del lunes. Los grupos tienen un máximo de diez personas. No hay clases por la mañana ni los fines de semana.',
 'The neighbourhood centre offers a photography course for adults. You do not need experience, but must bring a phone with a camera or a simple camera. Classes are Tuesdays and Thursdays from six to seven thirty. The course starts on November tenth and lasts four weeks. In the first week we learn to use light. Then we photograph objects and places in the neighbourhood. The last class is in the park if the weather is good. If it rains, we work inside the centre. The course costs sixty euros. To reserve a place, write to the centre before Monday. Groups have a maximum of ten people. There are no morning or weekend classes.',
 [['llevar','to bring / carry'],['plaza','place / spot'],['durar','to last'],['máximo','maximum']],[
 q('¿Necesitas experiencia en fotografía?','No.',['Sí, dos años.','Sí, un curso anterior.'],'El anuncio dice explícitamente que no necesitas experiencia.','The announcement explicitly says experience is not required.'),
 q('¿Qué tienes que llevar?','Un teléfono con cámara o una cámara.',['Un ordenador nuevo.','Diez fotografías impresas.'],'Se puede llevar un teléfono con cámara o una cámara sencilla.','Either a camera phone or a simple camera is acceptable.'),
 q('¿A qué hora terminan las clases?','A las siete y media.',['A las seis.','A las diez.'],'El horario va de seis a siete y media.','Classes run from six until seven thirty.'),
 q('¿Qué pasa con la última clase si llueve?','Se hace dentro del centro.',['Se cancela todo el curso.','Se hace siempre en el parque.'],'La alternativa de lluvia es trabajar dentro del centro.','The rain alternative is working inside the centre.'),
 q('¿Cuál es el máximo de personas por grupo?','Diez.',['Cuatro.','Sesenta.'],'Diez es el máximo de personas; cuatro son semanas y sesenta es el precio.','Ten is the group maximum; four refers to weeks and sixty to the price.')],
 'Pregunta por una plaza y confirma si puedes asistir en ese horario.', 'Ask for a place and confirm whether you can attend at those times.')
];
// Keep new-bank option rotation local so old banks retain their answer positions.
a2Library.forEach((text,ti)=>text.questions.forEach((item,i)=>{const shift=(ti+i)%3;item.options=item.options.slice(shift).concat(item.options.slice(0,shift));item.answer=(3-shift)%3;}));
export const a2Conversation=[['Mi barrio','Describe tu barrio: qué hay, dónde están dos lugares y cuál te gusta.'],['Mi rutina','Cuenta tu rutina con tres actividades y pregunta a tu pareja por la suya.'],['Un plan para el sábado','Propón un plan para el sábado con hora, lugar y una alternativa.'],['En la tienda','Pide dos productos en una tienda y pregunta cuánto cuestan.'],['Una salida de ayer','Cuenta una salida terminada: primero, después y al final.'],['Antes y ahora','Compara una costumbre de antes con lo que haces ahora.']];
